}, {"id": "https://openalex.org/W4394934135", "doi": "https://doi.org/10.1162/artl_a_00430", "title": "A Procedure for Testing for Tokyo Type 1 Open-Ended Evolution", "publication_year": 2024, "type": "article", "cited_by_count": 1, "open_access": {"is_oa": false, "oa_status": "closed", "oa_url": null, "any_repository_has_fulltext": false}, "primary_location": {"id": "doi:10.1162/artl_a_00430", "doi": "https://doi.org/10.1162/artl_a_00430", "is_oa": false, "landing_page_url": "https://doi.org/10.1162/artl_a_00430", "pdf_url": null, "source": {"id": "https://openalex.org/S2181302", "display_name": "Artificial Life", "issn_l": "1064-5462", "issn": ["1064-5462", "1530-9185"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["anvur-class-a", "anvur-scientific", "ccf-c", "cwts-core", "dongbi-c", "jufo-2", "ki-jl-2", "medline", "norway-2", "poland-40", "russia-white-list-2"], "host_organization": "https://openalex.org/P4310315718", "host_organization_name": "The MIT Press", "host_organization_lineage": ["https://openalex.org/P4310315718", "https://openalex.org/P4310316440"], "host_organization_lineage_names": ["The MIT Press", "Massachusetts Institute of Technology"], "type": "journal"}, "license": null, "license_id": null, "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Artificial Life", "raw_type": "journal-article"}, "abstract": "Tokyo Type 1 open-ended evolution (OEE) is a category of OEE that includes systems exhibiting the ongoing generation of adaptive novelty and ongoing growth in complexity. It can be considered as a necessary foundation for Tokyo Type 2 OEE (ongoing evolution of evolvability) and Tokyo Type 3 OEE (ongoing generation of major transitions). This article brings together five methods of analysis to form a procedure for testing for Tokyo Type 1 OEE. The procedure is presented as simply as possible, isolated from the complexities of any particular evolutionary system, and with a clear rationale for each step. In developing these steps, we also identify five key challenges in OEE. The last of these (achieving a higher order of complexity growth within a system exhibiting indefinitely scalable complexity) can be considered a grand challenge for Tokyo Type 1 OEE. Promising approaches to this grand challenge include also achieving one or both of Tokyo Types 2 and 3 OEE; this can be seen as one answer to why these other types of OEE are important, providing a unified view of OEE."}]", "excerpt_truncated": true, "source_sha256": "d0628b32ee34a2487aefd5ef5394d3cdc91b4b1bb5450bd7bc58946dd15ba489", "verification_required": true, "topic_domain": "unprompted_complexity", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1162/artl_a_00254", "doi:10.1162/artl_a_00430", "openalex:W2570466731", "openalex:W4394934135", "arxiv:1606.01810"], "source_candidates": ["https://doi.org/10.1162/artl_a_00254", "https://arxiv.org/pdf/1606.01810", "https://doi.org/10.1162/artl_a_00430"], "source_candidate_identities": {}}

